@Service()
export class PharmacyOrderRepository extends BaseRepository<IPharmacyOrder> {
  constructor() {
    super(PharmacyOrderModel as Model<IPharmacyOrder>);
  }

  private applyCommonFilters(query: Record<string, unknown>, filter: OrderQueryParams): Record<string, unknown> {
    const effectiveCustomerId = filter.userId || filter.customerId;
    if (effectiveCustomerId) {
      query.customerId = effectiveCustomerId;
    }
    if (filter.buyerPharmacyId) {
      query.buyerPharmacyId = filter.buyerPharmacyId;
    }
    if (filter.orderType) {
      query.orderType = filter.orderType;
    }
    if (filter.orderFor === 'consultation') {
      query.linkedConsultationId = { $exists: true, $ne: null };
    }
    if (filter.orderFor === 'diagnostic') {
      query.linkedDiagnosticOrderId = { $exists: true, $nin: [null, ''] };
    }
    if (filter.status) query.status = filter.status;
    if (filter.paymentStatus) query.paymentStatus = filter.paymentStatus;

    return query;
  }

async consumeOrderReservedStockBulk(
  pharmacyId: string,
  items: Array<{ medicineId: string; batchAllocations?: IInventoryBatchAllocation[] }>,
  session: ClientSession
): Promise<void> {
  for (const item of items) {
    if (!item.batchAllocations?.length) continue;
    const consumed = await this.inventoryItemRepo.consumeBatchAllocations(
      pharmacyId,
      item.medicineId,
      item.batchAllocations,
      session
    );
    if (!consumed) {
      throw new AppError({
        status: 409,
        code: 'BATCH_RESERVATION_CONSUME_FAILED',
        message: `Reserved batch stock could not be consumed for medicine ${item.medicineId}`,
      });
    }
  }
}

async consumeBatchAllocations(
  pharmacyId: string,
  medicineId: string,
  allocations: IInventoryBatchAllocation[],
  session: ClientSession
): Promise<IInventoryItem | null> {
  const document = await InventoryItemModel.findOne({ pharmacyId, medicineId }).session(session);
  if (!document) return null;

  let total = 0;
  const today = new Date().toISOString().slice(0, 10).replace(/-/g, '');
  for (const allocation of allocations) {
    const batch = (document.batches || []).find(
      (candidate) => String((candidate as any)._id) === String(allocation.batchId)
    );
    if (
      !batch ||
      batch.status !== 'active' ||
      batch.expiryDate < today ||
      batch.reservedQty < allocation.quantity
    ) return null;
    batch.reservedQty -= allocation.quantity;
    if (batch.availableQty === 0 && batch.reservedQty === 0) {
      batch.status = 'depleted';
      batch.depletedAt = new Date();
    }
    total += allocation.quantity;
  }

  if (document.reservedQty < total) return null;
  document.reservedQty -= total;
  document.markModified('batches');
  const saved = await document.save({ session });
  return saved.toObject() as IInventoryItem;
}

